              </div>
              <p className="text-sm text-muted-foreground">Thanks for joining.</p>
              <button
                onClick={() => {
                  setStatus("idle")
                  setEmail("")
                  setError("")
                }}
                className="text-xs font-medium text-primary underline underline-offset-4 hover:text-primary/80"
              >
                Subscribe another address
              </button>
            </motion.div>
